```json
{
  "source_url": "https://github.com/ethereum/EIPs/blob/master/EIPS/eip-7594.md",
  "title": "EIP-7594: PeerDAS - Peer Data Availability Sampling",
  "category": "EIP",
  "layer": "consensus+networking",
  "sub_graphs": [
    {
      "id": "SG-7594-001",
      "name": "Erasure Coding and Data Matrix",
      "description": "Extends EIP-4844 blobs using 1D erasure coding. Each row = blob data + erasure code, subdivided into cells. Columns = cells from all rows at a specific index. Nodes can reconstruct full data matrix with >=50% of columns.",
      "invariants": [
        {"id": "INV-7594-001", "text": "A node can reconstruct the entire data matrix if it acquires at least 50% of all columns."},
        {"id": "INV-7594-002", "text": "Each cell can be authenticated against its respective blob's KZG commitment."}
      ],
      "functions": [
        {"id": "FN-7594-001", "signature": "compute_cells(blob) -> Cell[]", "description": "Outputs all cells of a blob, including extension cells."},
        {"id": "FN-7594-002", "signature": "recover_matrix(columns) -> DataMatrix", "description": "Reconstructs the full data matrix from at least 50% of columns."}
      ],
      "state_variables": [
        {"id": "SV-7594-001", "name": "CELLS_PER_EXT_BLOB", "description": "Number of cells for an extended blob (defined in consensus specs)."}
      ],
      "data_structures": [
        {"id": "DS-7594-001", "name": "Cell", "description": "Smallest unit of blob data that can be authenticated with KZG commitments."},
        {"id": "DS-7594-002", "name": "Column", "description": "Cross-section across all blobs at a specific index; associated with a gossip subnet."},
        {"id": "DS-7594-003", "name": "DataMatrix", "description": "Full matrix of rows (blobs + erasure codes) and columns."}
      ]
    },
    {
      "id": "SG-7594-002",
      "name": "Custody and Sampling",
      "description": "Deterministic assignment of column subnets to nodes based on node ID. Nodes maintain diverse peer sets and sample columns every slot to perform DAS.",
      "invariants": [
        {"id": "INV-7594-003", "text": "Each node is responsible for maintaining a deterministic set of column subnets as a function of their node ID."},
        {"id": "INV-7594-004", "text": "Nodes MUST sample columns from peers to perform DAS every slot."},
        {"id": "INV-7594-005", "text": "Validators have additional custody requirements beyond full nodes, scaling with validator count."}
      ],
      "functions": [],
      "state_variables": [
        {"id": "SV-7594-002", "name": "NUMBER_OF_CUSTODY_GROUPS", "description": "Total number of sampling groups (m in security analysis)."},
        {"id": "SV-7594-003", "name": "SAMPLES_PER_SLOT", "description": "Minimum number of samples a node must download per slot (k in security analysis)."},
        {"id": "SV-7594-004", "name": "CUSTODY_REQUIREMENT", "description": "Minimum number of custody groups a full node must maintain."}
      ],
      "data_structures": []
    },
    {
      "id": "SG-7594-003",
      "name": "Blob Transaction Limit",
      "description": "Introduces a limit of 6 blobs per transaction, enforced at submission, network receipt, and block production/processing.",
      "invariants": [
        {"id": "INV-7594-006", "text": "Clients MUST enforce a limit of 6 blobs per transaction at submission time, when received from the network, and during block production and processing."}
      ],
      "functions": [],
      "state_variables": [
        {"id": "SV-7594-005", "name": "BLOB_COUNT_LIMIT", "value": 6, "description": "Maximum number of blobs per transaction."}
      ],
      "data_structures": []
    },
    {
      "id": "SG-7594-004",
      "name": "Transaction Wrapper Modification",
      "description": "Modifies EIP-4844 transaction pool wrapper to include cell KZG proofs instead of blob proofs, adding wrapper_version field.",
      "invariants": [
        {"id": "INV-7594-007", "text": "There MUST be an equal number of tx_payload_body.blob_versioned_hashes, blobs, and commitments."},
        {"id": "INV-7594-008", "text": "cell_proofs MUST contain exactly CELLS_PER_EXT_BLOB * len(blobs) cell proofs."},
        {"id": "INV-7594-009", "text": "kzg_to_versioned_hash(commitments[i]) == tx_payload_body.blob_versioned_hashes[i] for all i."},
        {"id": "INV-7594-010", "text": "KZG commitments MUST match the corresponding blobs and cell_proofs, verified via compute_cells and verify_cell_kzg_proof_batch."}
      ],
      "functions": [
        {"id": "FN-7594-003", "signature": "kzg_to_versioned_hash(commitment) -> VersionedHash", "description": "Hashes KZG commitment to versioned hash for validation."},
        {"id": "FN-7594-004", "signature": "verify_cell_kzg_proof_batch(commitments, cells, proofs) -> bool", "description": "Batch verifies all cell KZG proofs against commitments."}
      ],
      "state_variables": [
        {"id": "SV-7594-006", "name": "wrapper_version", "value": 1, "description": "One byte indicating wrapper version; set to 1 for this version."}
      ],
      "data_structures": [
        {"id": "DS-7594-004", "name": "PooledTransactionWrapper", "description": "rlp([tx_payload_body, wrapper_version, blobs, commitments, cell_proofs])"},
        {"id": "DS-7594-005", "name": "cell_proofs", "description": "List of cell proofs for all blobs, CELLS_PER_EXT_BLOB proofs per blob, including extension indices."}
      ]
    },
    {
      "id": "SG-7594-005",
      "name": "Security Model - Data Withholding Resistance",
      "description": "Randomized sampling scheme that decreases the probability of successful data withholding attacks as network size grows. With 10,000 nodes, tricking >2% of nodes has probability < 10^-20.",
      "invariants": [
        {"id": "INV-7594-011", "text": "The probability of a successful withholding attack decreases sublinearly as the network grows, for a sublinear amount of data downloaded."},
        {"id": "INV-7594-012", "text": "For n=10000 nodes, tricking epsilon=0.02 (200 nodes) has upper bound probability of 10^-20.04."},
        {"id": "INV-7594-013", "text": "For n=10000 nodes, tricking epsilon=0.05 (500 nodes) has upper bound probability of 10^-306.34."}
      ],
      "functions": [],
      "state_variables": [
        {"id": "SV-7594-007", "name": "n", "description": "Total number of sampling nodes (network size)."},
        {"id": "SV-7594-008", "name": "m", "description": "Total number of samples possible (NUMBER_OF_CUSTODY_GROUPS)."},
        {"id": "SV-7594-009", "name": "k", "description": "Minimum samples per node (SAMPLES_PER_SLOT)."}
      ],
      "data_structures": []
    }
  ],
  "metadata": {
    "timestamp": "2026-02-05T00:00:00Z",
    "eip_status": "Final",
    "requires": ["EIP-4844"],
    "backwards_compatible": true
  }
}
```

